<header class="flex min-h-[80px] items-center justify-between gap-4 border-b border-slate-200 bg-white px-4 sm:px-8"><div class="flex items-center gap-3"><button type="button" @click="sidebarOpen=!sidebarOpen" aria-label="Buka menu" class="h-11 w-11 rounded-lg text-slate-600"><svg class="mx-auto h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path stroke-width="2" stroke-linecap="round" d="M4 6h16M4 12h16M4 18h16"/></svg></button><span class="text-sm font-semibold text-slate-700">Laporan kerja harian</span></div><a href="/contributors.html" class="text-sm font-semibold text-brand-700">Teams & Kontributor →</a></header>
<section x-data="adminWorkReportsData()" class="mx-auto w-full max-w-6xl space-y-6 p-4 sm:p-8"><div><p class="text-xs font-bold uppercase tracking-widest text-brand-700">Aktivitas tim</p><h1 class="mt-2 text-2xl font-extrabold text-slate-900">Laporan kerja harian</h1><p class="mt-2 text-sm text-slate-500">Rekap durasi dan HP yang dilaporkan kontributor dari akun masing-masing.</p></div><p x-show="error" x-text="error" role="alert" class="rounded-xl bg-red-50 p-4 text-sm text-red-700"></p><div class="flex flex-wrap gap-3 rounded-2xl border border-slate-200 bg-white p-5"><label class="text-xs font-semibold text-slate-600">Tanggal<input type="date" x-model="date" @change="load()" class="mt-2 block h-11 rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><label class="min-w-[180px] flex-1 text-xs font-semibold text-slate-600">Cari nama<input type="search" x-model="search" placeholder="Nama kontributor…" class="mt-2 block h-11 w-full rounded-lg border border-slate-200 px-3 text-sm font-normal"></label><button type="button" @click="load()" :disabled="loading" class="mt-auto h-11 rounded-lg border border-brand-200 px-4 text-sm font-semibold text-brand-700">Muat ulang</button></div><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Laporan diterima pada tanggal ini</p><p class="mt-2 text-2xl font-bold" x-text="rows.length+' orang'"></p></div><div class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">Total durasi dilaporkan</p><p class="mt-2 text-2xl font-bold text-brand-700" x-text="duration(total)"></p></div></div><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="p-5"><h2 class="font-bold" x-text="dateLabel(date)"></h2></div><div class="overflow-x-auto"><table class="w-full min-w-[540px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4">Nama kontributor</th><th class="p-4">Total durasi</th><th class="p-4">HP yang dipakai</th></tr></thead><tbody><template x-for="report in filtered" :key="report.id"><tr class="border-t border-slate-100"><td class="p-4 font-semibold" x-text="report.contributor_name"></td><td class="p-4 font-semibold text-brand-700" x-text="duration(report.total_duration_minutes)"></td><td class="p-4" x-text="phoneNames(report.phones)"></td></tr></template></tbody></table></div><p x-show="loading" class="p-8 text-center text-sm text-slate-500">Memuat laporan…</p><p x-show="!loading&&!filtered.length" class="p-8 text-center text-sm text-slate-500">Belum ada laporan yang cocok pada tanggal ini.</p></div></section>
